import json,base64,sys,re
from collections import defaultdict
keep=set(json.load(open('outrx.json')))
meds=json.load(open('meds.json'))
mr=defaultdict(list)
for l in open('MedicationRequest.ndjson'):
    r=json.loads(l)
    if r['id'] in keep: mr[r['subject']['reference'][8:]].append(r)
notes=defaultdict(list)
for l in open('DocumentReference.ndjson'):
    r=json.loads(l)
    if r.get('subject'): notes[r['subject']['reference'][8:]].append(r)
labs=defaultdict(list)
for l in open('Observation.ndjson'):
    if not any(k in l for k in ('INR','Magnesium','Potassium')): continue
    o=json.loads(l)
    cc=o.get('code',{}).get('coding',[{}])[0]; disp=cc.get('display','')
    if disp not in ('INR','INR(PT)','Magnesium','Potassium','Potassium (serum)'): continue
    t=o.get('effectiveDateTime','')
    if t<'2025-06': continue
    labs[o['subject']['reference'][8:]].append((t,disp,o.get('valueQuantity',{}).get('value'),o['id']))
conds=defaultdict(list)
for l in open('Condition.ndjson'):
    o=json.loads(l); cc=o['code']['coding'][0]
    conds[o['subject']['reference'][8:]].append((cc['code'],cc.get('display'),o['id'],o.get('encounter',{}).get('reference','')[9:]))
encs={}
for l in open('Encounter.ndjson'):
    e=json.loads(l); encs[e['id']]=(e.get('period',{}).get('start','')[:10],e.get('class',{}).get('code'))
ecgs=defaultdict(list)
for e in json.load(open('ecgs.json'))['ecgs']: ecgs[e['patient']].append(e)
pats={p['id']:p for p in (json.loads(l) for l in open('patients.ndjson'))}
def dump(pref,cardonly=True):
    pid=[k for k in pats if k.startswith(pref)][0]
    p=pats[pid]; out=[]
    out.append('PATIENT %s dob=%s sex=%s deceased=%s'%(pid,p['birthDate'],p['gender'],p.get('deceasedDateTime')))
    out.append('ECGs: '+', '.join('%s@%s'%(e['ecg'],e['time']) for e in sorted(ecgs[pid],key=lambda x:x['time'])))
    out.append('-- OUTPT RX --')
    for r in sorted(mr[pid],key=lambda r:r['authoredOn']):
        vp=r['dispenseRequest']['validityPeriod']; di=r['dosageInstruction'][0]
        out.append('%s | auth %s | %s | %s %s | %s -> %s'%(r['id'],r['authoredOn'][:10],meds.get(r['medicationReference']['reference'][11:]),di.get('text'),di['timing']['code']['coding'][0]['code'],vp['start'][:10],vp['end'][:10]))
    out.append('-- CARDIAC/BLEED CONDITIONS --')
    seen=set()
    for c in sorted(conds[pid],key=lambda c:encs.get(c[3],('',''))[0]):
        if c[:2] in seen: continue
        seen.add(c[:2])
        if cardonly and not re.search(r'fibrill|flutter|hemorrhag|bleed|stroke|infarct|heart failure|thrombocytopen|anemia|aneurysm|cerebral|intracran|embol|thrombo|fall|diabet|hypertens|vascular|renal|kidney|cardiomyopath|valve|tachycard|bradycard|block|pacemaker|syncope',str(c[1]),re.I): continue
        out.append('%s | %s | %s | enc %s'%(c[0],c[1],c[2],encs.get(c[3],('?',''))))
    out.append('-- LABS 2025-06+ --')
    for t in sorted(labs[pid]): out.append('%s | %s = %s | %s'%t)
    out.append('-- NOTES --')
    for r in sorted(notes[pid],key=lambda r:r['date']):
        txt=base64.b64decode(r['content'][0]['attachment']['data']).decode()
        out.append('### %s | %s | %s | %s\n%s'%(r['id'],r['date'],r['type']['coding'][0]['display'],[e['valueCode'] for e in r.get('extension',[])],txt))
    return '\n'.join(out)
if __name__=='__main__':
    for a in sys.argv[1:]: print('#'*70); print(dump(a))
EOF
